import * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';
import { RotationDriver, normalizeAxis, quaternionFromAxisAngle } from './rotation';
import type {
  ObstacleBodyHandle,
  ObstacleBodySpec,
  ObstacleColliderSpec,
  ObstaclePhysicsAdapter,
  RotatingObstacleLifecycle,
} from './types';
import { IDENTITY_QUATERNION } from './types';
import { requireId, requireVec3 } from './validation';

export interface RotatingObstacleOptions {
  id: string;
  position: Vec3;
  axis?: Vec3;
  speed?: number;
  phase?: number;
  enabled?: boolean;
  maxStepSeconds?: number;
  scene?: THREE.Scene;
  physics?: ObstaclePhysicsAdapter;
}

export abstract class RotatingObstacle implements RotatingObstacleLifecycle {
  readonly id: string;
  readonly root = new THREE.Group();
  readonly pivot = new THREE.Group();
  readonly axis: Vec3;
  readonly speed: number;
  readonly phase: number;
  enabled: boolean;

  protected readonly position: Vec3;
  protected readonly driver: RotationDriver;
  protected readonly scene?: THREE.Scene;
  protected readonly physics?: ObstaclePhysicsAdapter;
  protected bodyHandle?: ObstacleBodyHandle;
  protected disposed = false;

  protected constructor(options: RotatingObstacleOptions) {
    this.id = requireId(options.id, 'rotating obstacle');
    this.position = requireVec3(options.position, 'obstacle position');
    this.axis = normalizeAxis(options.axis ?? { x: 0, y: 1, z: 0 });
    this.speed = options.speed ?? 1;
    this.phase = options.phase ?? 0;
    this.enabled = options.enabled ?? true;
    this.scene = options.scene;
    this.physics = options.physics;
    this.driver = new RotationDriver({
      speed: this.speed,
      phase: this.phase,
      maxStepSeconds: options.maxStepSeconds,
    });

    this.root.position.set(this.position.x, this.position.y, this.position.z);
    this.root.add(this.pivot);
    this.scene?.add(this.root);
    this.applyRotation();
  }

  get angle(): number { return this.driver.angle; }
  get rotation(): Quat { return quaternionFromAxisAngle(this.axis, this.angle); }
  get isDisposed(): boolean { return this.disposed; }

  protected mountBody(colliders: readonly ObstacleColliderSpec[], kind: ObstacleBodySpec['kind'] = 'kinematic'): void {
    if (!this.physics || this.bodyHandle) return;
    this.bodyHandle = this.physics.createBody({
      id: this.id,
      kind,
      position: { ...this.position },
      rotation: { ...IDENTITY_QUATERNION },
      colliders,
    });
    this.bodyHandle.setNextRotation(this.rotation);
  }

  protected applyRotation(): void {
    const rotation = this.rotation;
    this.pivot.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
    this.bodyHandle?.setNextRotation(rotation);
  }

  update(deltaSeconds: number): void {
    if (this.disposed || !this.enabled) return;
    this.driver.advance(deltaSeconds);
    this.applyRotation();
  }

  setElapsed(seconds: number): void {
    if (this.disposed) return;
    this.driver.setElapsed(seconds);
    this.applyRotation();
  }

  reset(): void {
    if (this.disposed) return;
    this.driver.reset();
    this.applyRotation();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.bodyHandle?.dispose();
    this.bodyHandle = undefined;
    this.root.removeFromParent();
  }
}
